-- Q09: 低空经济：全国在招岗位总数
-- Actual statements captured from execution evidence.
-- queryId: target:base; completed: true
SELECT JSON_OBJECT('row',JSON_OBJECT(CONVERT(X'636f756e74' USING utf8mb4),COUNT(*))) FROM (SELECT DISTINCT pc.position_id FROM c_position_chain pc WHERE pc.deleted=0 AND pc.industry_chain_id IN (19,1063,1130,1169,15926,15927,15928,15929,15930,15931,15932,15933,15934,15935,15936,15937,15938,15939,15940,15941,15942,15943,15944,15945,15946,15947,15948,15949,15950,15951,15952,15953,15954,15955,15956,15957,15958,15959,15960,15961,15962,15963,15964,15965,15966,15967,15968,15969,15970,15971,15972,15973,15974,15975,15976,15977,15978,15979,15980,15981,15982,15983,15984,15985,15986,15987,15988,15989,15990,15991,15992,15993,15994,15995,15996,15997,15998)) industry_candidates JOIN c_company_position p ON p.id=industry_candidates.position_id WHERE p.publish_state='PUBLISHING' AND p.deleted=0;
